CREATE TABLE [dbo].[RIA_FORMATOS](	  [id_formato] INT NOT NULL	, [nombre] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [id_creador] SMALLINT NOT NULL	, [fecha_creado] SMALLDATETIME NOT NULL DEFAULT(getdate())	, [activo] BIT NOT NULL DEFAULT((1))	, [peso] INT NOT NULL	, [version] INT NOT NULL DEFAULT((1))	, [tipo] INT NOT NULL DEFAULT((0))	, CONSTRAINT [PK_RIA_FORMATOS] PRIMARY KEY ([id_formato] ASC, [version] ASC))